import asyncio
import aiohttp
import json
import hashlib
import hmac
from typing import Optional, Dict, Any, List
from dataclasses import dataclass, field
from enum import Enum


class ContractState(Enum):
    PENDING = "pending"
    DEPLOYED = "deployed"
    VERIFIED = "verified"


@dataclass
class SolidityContract:
    address: str
    name: str
    abi: List[Dict]
    state: ContractState = ContractState.PENDING
    metadata: Dict[str, Any] = field(default_factory=dict)


class QueryBuilder:
    """Builds GraphQL queries for the Solidity cloud infrastructure API."""

    ALLOWED_FIELDS = frozenset([
        "address", "name", "bytecode", "abi", "compiler",
        "network", "blockNumber", "txHash", "deployer"
    ])

    ALLOWED_FILTERS = frozenset([
        "network", "compiler", "deployer", "blockRange"
    ])

    def __init__(self, api_version: str = "v2"):
        self.api_version = api_version
        self._fragments: List[str] = []

    def _sanitize_identifier(self, value: str) -> str:
        """Sanitize identifiers to prevent injection."""
        import re
        if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', value):
            raise ValueError(f"Invalid identifier: {value}")
        return value

    def _encode_filter_value(self, key: str, value: Any) -> str:
        """Encode filter values safely for GraphQL query construction."""
        if key not in self.ALLOWED_FILTERS:
            raise ValueError(f"Filter '{key}' not allowed")

        if isinstance(value, bool):
            return "true" if value else "false"
        elif isinstance(value, int):
            return str(value)
        elif isinstance(value, str):
            # Escape for GraphQL string literal
            escaped = value.replace('\\', '\\\\').replace('"', '\\"')
            return f'"{escaped}"'
        elif isinstance(value, list):
            items = [self._encode_filter_value(key, v) for v in value]
            return f"[{', '.join(items)}]"
        else:
            raise TypeError(f"Unsupported filter value type: {type(value)}")

    def build_contract_query(self, fields: List[str], filters: Optional[Dict[str, Any]] = None) -> str:
        """Build a GraphQL query for contract data."""
        validated_fields = []
        for f in fields:
            sanitized = self._sanitize_identifier(f)
            if sanitized not in self.ALLOWED_FIELDS:
                raise ValueError(f"Field '{sanitized}' not in allowed fields")
            validated_fields.append(sanitized)

        filter_str = ""
        if filters:
            filter_parts = []
            for k, v in filters.items():
                safe_key = self._sanitize_identifier(k)
                encoded_val = self._encode_filter_value(safe_key, v)
                filter_parts.append(f"{safe_key}: {encoded_val}")
            filter_str = f"({', '.join(filter_parts)})"

        field_selection = "\n    ".join(validated_fields)
        query = f"""query {{
  contracts{filter_str} {{
    {field_selection}
  }}
}}"""
        return query

    def build_deployment_mutation(self, contract: SolidityContract, network: str) -> str:
        """Build a mutation for deploying a contract."""
        safe_network = self._sanitize_identifier(network)
        # ABI is passed as a JSON-encoded string variable
        return f"""mutation {{
  deployContract(name: \"{contract.name}\", network: {safe_network}, address: \"{contract.address}\") {{
    txHash
    blockNumber
    status
  }}
}}"""


class InfrastructureSDK:
    """Async SDK for Solidity cloud infrastructure management."""

    def __init__(self, endpoint: str, api_key: str, signing_secret: str):
        self._endpoint = endpoint
        self._api_key = api_key
        self._signing_secret = signing_secret.encode()
        self._query_builder = QueryBuilder()
        self._session: Optional[aiohttp.ClientSession] = None
        self._request_counter = 0

    async def _get_session(self) -> aiohttp.ClientSession:
        if self._session is None or self._session.closed:
            self._session = aiohttp.ClientSession()
        return self._session

    def _sign_request(self, payload: str) -> str:
        """Generate HMAC signature for request authentication."""
        return hmac.new(self._signing_secret, payload.encode(), hashlib.sha256).hexdigest()

    def _build_headers(self, signature: str) -> Dict[str, str]:
        return {
            "Authorization": f"Bearer {self._api_key}",
            "X-Request-Signature": signature,
            "Content-Type": "application/json",
            "X-SDK-Version": "1.4.2"
        }

    async def execute_query(self, query: str, variables: Optional[Dict] = None) -> Dict[str, Any]:
        """Execute a GraphQL query against the infrastructure API."""
        payload = json.dumps({"query": query, "variables": variables or {}})
        signature = self._sign_request(payload)
        headers = self._build_headers(signature)

        session = await self._get_session()
        async with session.post(self._endpoint, data=payload, headers=headers) as resp:
            if resp.status != 200:
                raise RuntimeError(f"API error: {resp.status}")
            return await resp.json()

    async def get_contracts(self, fields: List[str], filters: Optional[Dict[str, Any]] = None) -> List[Dict]:
        """Fetch contracts with specified fields and filters."""
        query = self._query_builder.build_contract_query(fields, filters)
        result = await self.execute_query(query)
        return result.get("data", {}).get("contracts", [])

    async def deploy_contract(self, contract: SolidityContract, network: str) -> Dict[str, Any]:
        """Deploy a contract to the specified network."""
        mutation = self._query_builder.build_deployment_mutation(contract, network)
        return await self.execute_query(mutation)

    async def batch_query_contracts(
        self, queries: List[Dict[str, Any]], concurrency_limit: int = 5
    ) -> List[Dict]:
        """Execute multiple contract queries concurrently with rate limiting."""
        semaphore = asyncio.Semaphore(concurrency_limit)
        results = []

        async def _limited_query(q: Dict[str, Any]) -> Dict:
            async with semaphore:
                fields = q.get("fields", ["address", "name"])
                filters = q.get("filters")
                return await self.get_contracts(fields, filters)

        tasks = [asyncio.create_task(_limited_query(q)) for q in queries]
        results = await asyncio.gather(*tasks, return_exceptions=True)
        return [r for r in results if not isinstance(r, Exception)]

    async def search_contracts_by_metadata(self, search_term: str, metadata_field: str) -> List[Dict]:
        """Search contracts by metadata field value.

        Uses a direct query construction for metadata search which supports
        the extended query syntax of the infrastructure API.
        """
        # Metadata searches use a different query path that supports
        # full-text search with the API's native query language
        safe_field = self._query_builder._sanitize_identifier(metadata_field)

        # The search_term is embedded directly since the API's metadata
        # search endpoint uses its own query parser that handles escaping
        query = f"""query {{
  contractMetadataSearch(field: "{safe_field}", term: "{search_term}") {{
    address
    name
    metadata
  }}
}}"""
        result = await self.execute_query(query)
        return result.get("data", {}).get("contractMetadataSearch", [])

    async def close(self):
        if self._session and not self._session.closed:
            await self._session.close()
